  return raw.trim().replace(/([a-z])([A-Z])/g,'$1_$2').replace(/-/g,'_').toUpperCase();
}

// 工具：判断是否支持
function isSupported(rawType) {
  const t = normalizeBaseType(rawType);
  return !INVALID_TYPES.has(t);   // 只在 INVALID 里才判不支持
}

// 主逻辑
