// ========== 依赖 ==========
const CryptoJS = require('crypto-js');

// ========== 常量（与 Java 端完全一致） ==========
const INVALID_TYPES = ['DISCUSSION','MULTI_FILE_UPLOAD','EXIT_TICKET','MULTICHOICE','UNKNOWN'];
const STUDY_MODES   = ['RICH_TEXT_READ','TEXT_LEARN','VIDEO_POPUP','VOCABULARY','DISCUSSION','INPUT','VIDEO_POINT_READ'];

// ========== 小工具 ==========
function normalizeBaseType(raw){
  if(!raw||typeof raw!=='string') return 'UNKNOWN';
  return raw.trim().replace(/([a-z])([A-Z])/g,'$1_$2').replace(/-/g,'_').toUpperCase();
}
function getSubmitType(baseTypeRaw){
  const t=normalizeBaseType(baseTypeRaw);
  if(INVALID_TYPES.includes(t)) throw new Error('Unsupported BaseType: '+t);
  return STUDY_MODES.includes(t)?2:1;
}

// ========== AES ECB 解密 ==========
function decrypt(dataWithPrefix,k){
  if(!dataWithPrefix||!dataWithPrefix.startsWith('unipus.')) return dataWithPrefix;
  const hex=dataWithPrefix.slice('unipus.'.length);
  const key=CryptoJS.enc.Utf8.parse('1a2b3c4d'+k);
  const cipher=CryptoJS.enc.Hex.parse(hex);
  const dec=CryptoJS.AES.decrypt({ciphertext:cipher},key,{mode:CryptoJS.mode.ECB,padding:CryptoJS.pad.NoPadding});
  return dec.toString(CryptoJS.enc.Utf8).replace(/\0/g,'');
}

// ========== 提取答案 & instanceId（字符串） ==========
function extractAnswers(decrypted){
  if(!decrypted) return {instanceId:null,answers:[]};
  try{
    const list=JSON.parse(decrypted);
    if(!Array.isArray(list)||!list[0]) return {instanceId:null,answers:[]};
    const d=list[0];
    // 全程字符串，禁止数值运算
    const id=d.id?String(d.id):null;
    const ans=[];
    if(d.answer){
      const obj=JSON.parse(d.answer);
      (obj.children||[]).forEach(ch=>{
        if(ch.answers?.length) ans.push(ch.answers[0]);
      });
    }
    return {instanceId:id,answers:ans};
  }catch(e){
    console.error('提取答案失败:',e);
    return {instanceId:null,answers:[]};
  }
}

// ========== 构建提交体（与 Java 源码字段顺序一致） ==========
function buildBody({instanceId,answers,groupId,courseId,openId,questionType}){
