    question_type:'basic',
    payloads:[{recordDetail:{score:100,comment:''}}]
  }));

  // 顶层 body（字段顺序与 Java toJson 一致）
  const body={
    quesDatas:[{
      instanceId:instanceId||'123456',
      answer:JSON.stringify(answerObj),
      context:JSON.stringify({state:'submitted'}),
      contextVersion:0,
      answerVersion:0
    }],
    groupId,
    isCompleted:answers.map(()=>true),
    thirdPartyJudges:JSON.stringify(thirdPartyJudges),
    submitType,
    hideLoading:false,
    associationGroupId:'',
    courseId,
    openId,
    version:'default'
  };

  return JSON.stringify(body,null,2);
}

// ========== 主流程（取当前循环这一条） ==========
try{
