const CryptoJS = require('crypto-js');

// ====== 1. 适配 n8n 输入取值 ======
const inputItems = $input.all();
const firstInput = inputItems[0]?.json || {};
// 上游参数（保留你原有逻辑，适配实际场景可替换）
const cipherText = firstInput.data;
const k = firstInput.k;
const groupId = $('确定当前任务ID').item.json.taskId || firstInput.groupId || '';
const courseId = $('获取任务ID').item.json.value.courseStudyStrategy.instantId || firstInput.courseId || '';
const openId = $('登录').first().json.rs.openid || firstInput.openId || '';
const taskId = $('确定当前任务ID').item.json.taskId || '';
const questionType = $('提取baseType').item.json.requiredTaskBaseMap[taskId] || firstInput.questionType || 'DEFAULT';

// ====== 2. 核心常量（从 Java 源码提取）======
// 不支持的题型（对应 Java 中的 INVALID_TYPES）
const INVALID_TYPES = new Set(['RICH_TEXT_READ', 'VIDEO_POPUP', 'VOCABULARY', 'TEXT_LEARN']);
// 预设题型（返回空答案提交体，对应 Java 中的 PRESET_MODES）
const PRESET_MODES = new Set(['VIDEO', 'AUDIO', 'READING']);
// 学习类题型（submitType=2，否则=1，对应 Java 中的 STUDY_MODES）
const STUDY_MODES = new Set(['VOCABULARY', 'TEXT_LEARN', 'STUDY']);

// ====== 3. 工具函数 ======
// 移除空字节（\u0000）
function removeNullBytes(str) {
  return str ? str.replace(/\u0000/g, '') : '';
}

// WordArray 转 UTF8 字符串（兜底逻辑）
function wordArrayToUtf8(wordArray) {
  try {
    let str = CryptoJS.enc.Utf8.stringify(wordArray);
    if (str && str !== '[object Object]') return str;

    const base64Str = wordArray.toString(CryptoJS.enc.Base64);
    return CryptoJS.enc.Base64.parse(base64Str).toString(CryptoJS.enc.Utf8);
  } catch (e) {
    const bytes = [];
    for (let i = 0; i < wordArray.words.length; i++) {
      const word = wordArray.words[i];
      bytes.push((word >> 24) & 0xff);
      bytes.push((word >> 16) & 0xff);
      bytes.push((word >> 8) & 0xff);
      bytes.push(word & 0xff);
    }
    while (bytes[bytes.length - 1] === 0) bytes.pop();
    return bytes.map(b => String.fromCharCode(b)).join('');
  }
}

// PKCS7 补位移除
function removePkcs7Padding(str) {
  if (!str) return str;
  const paddingLen = str.charCodeAt(str.length - 1);
  return (paddingLen > 0 && paddingLen <= 16) ? str.slice(0, -paddingLen) : str;
}

// ====== 4. AES ECB 解密 ======
function decrypt(dataWithPrefix, keySuffix) {
  if (!dataWithPrefix || !dataWithPrefix.startsWith('unipus.')) {
    return removeNullBytes(dataWithPrefix);
  }

  try {
    const hexStr = dataWithPrefix.slice('unipus.'.length);
    const key = CryptoJS.enc.Utf8.parse('1a2b3c4d' + keySuffix);
    const ciphertext = CryptoJS.enc.Hex.parse(hexStr);

    const decryptedWA = CryptoJS.AES.decrypt(
      { ciphertext: ciphertext },
      key,
      { mode: CryptoJS.mode.ECB, padding: CryptoJS.pad.NoPadding }
    );

    let decryptedStr = wordArrayToUtf8(decryptedWA);
    decryptedStr = removePkcs7Padding(decryptedStr);
    return removeNullBytes(decryptedStr);
  } catch (e) {
    console.error('解密异常:', e.message);
    return '';
  }
}

// ====== 5. 答案/实例ID提取 ======
function extractAnswersAndInstanceId(decryptedStr) {
  let instanceId = null;
  const answers = [];

  if (!decryptedStr) {
    return { instanceId, answers };
  }

  try {
    const list = JSON.parse(decryptedStr);
    if (!Array.isArray(list) || list.length === 0) {
      return { instanceId, answers };
    }

    const firstItem = list[0];
    // 提取 instanceId（兼容大数/字符串）
    instanceId = firstItem.id ? String(firstItem.id) : null;

    // 解析多层转义的 answer 字段
    if (firstItem.answer) {
      const answerObj = typeof firstItem.answer === 'string' 
        ? JSON.parse(firstItem.answer.replace(/\\\\/g, '\\')) 
        : firstItem.answer;

      // 提取所有 answers 第一个值
      (answerObj.children || []).forEach(child => {
        if (Array.isArray(child.answers) && child.answers.length > 0) {
          answers.push(child.answers[0]);
        }
      });
    }
  } catch (e) {
    console.error('解析答案异常:', e.message);
  }

  // 兜底 instanceId
  return { 
    instanceId: instanceId || '1452178977371979800', 
    answers 
  };
}

// ====== 6. 生成提交请求体（复刻 Java 源码逻辑）======
function createSubmitBody(instanceId, answers, groupId, courseId, openId, questionType) {
  // 处理不支持的题型
  if (INVALID_TYPES.has(questionType)) {
    throw new Error(`Unsupported question type: ${questionType}`);
  }

  // 预设题型返回空答案提交体
  if (PRESET_MODES.has(questionType)) {
    return JSON.stringify({
      "quesDatas": [],
      "groupId": groupId,
      "isCompleted": [],
      "thirdPartyJudges": "[]",
      "submitType": 2,
      "hideLoading": true,
      "associationGroupId": "",
      "courseId": courseId,
      "openId": openId,
      "version": "default"
    }, null, 2);
  }

  // 构造正常题型的请求体
  const quesDatas = [];
  const isCompleted = [];
  const thirdPartyJudges = [];
  const children = [];

  // 构建 answer.children
  answers.forEach(answ => {
    // 处理非法字符（简化版，对应 Java 的 StringProcesser）
    const cleanAnsw = answ.replace(/[^\w\s]/g, '').trim();
    children.push({
      "value": [cleanAnsw],
      "isDone": true
    });

    // 构建 thirdPartyJudges 项
    thirdPartyJudges.push({
      "value": cleanAnsw,
      "question_type": mapQuestionType(questionType),
      "payloads": [{
        "recordDetail": {
          "score": 100.00,
          "comment": ""
        }
      }]
    });

    isCompleted.push(true);
  });

  // 构建 answer 字段
  const answer = {
    "value": [],
    "children": children,
    "progress": {},
    "record": {
      "url": ""
    }
  };

  // 构建 quesData 项
  const quesData = {
    "instanceId": instanceId,
    "answer": JSON.stringify(answer),
    "context": JSON.stringify({ "state": "submitted" }),
    "contextVersion": 0,
    "answerVersion": 0
  };
  quesDatas.push(quesData);

  // 确定 submitType
  const submitType = STUDY_MODES.has(questionType) ? 2 : 1;

  // 最终请求体
  const body = {
    "quesDatas": quesDatas,
    "groupId": groupId,
    "isCompleted": isCompleted,
    "thirdPartyJudges": JSON.stringify(thirdPartyJudges),
    "submitType": submitType,
    "hideLoading": false,
    "associationGroupId": "",
    "courseId": courseId,
    "openId": openId,
    "version": "default"
  };

  // 格式化输出（便于阅读）
  return JSON.stringify(body, null, 2);
}

// 题型映射（对应 Java 的 mapQuestionType）
function mapQuestionType(type) {
  const name = type.toLowerCase();
  if (name.includes('banked') || name.includes('cloze')) {
    return "material-banked-cloze";
  }
  return name.replace('_', '-');
}

// ====== 7. 主流程（整合所有逻辑）======
try {
  // 解密 + 提取答案/instanceId
  const decryptedData = decrypt(cipherText, k);
  const { instanceId, answers } = extractAnswersAndInstanceId(decryptedData);

  // 生成提交请求体
  const body = createSubmitBody(instanceId, answers, groupId, courseId, openId, questionType);

  // 最终输出（包含原有字段 + 新增 body 字段）
  const output = [
    {
      json: {
        instanceId: instanceId,
        answers: answers,
        decryptedData: decryptedData,
        body: body // 新增的请求体字段
      }
    }
  ];

  return output;
} catch (e) {
  return [
    {
      json: {
        error: e.message,
        instanceId: '1452178977371979800',
        answers: [],
        decryptedData: '',
        body: ''
      }
    }
  ];
}

// 取上游数据
